	loadSprite("F9_ScannerBG",97,87,0)

	loadExtendedSprite(unpac_noheader(F9_BG),"F9_BG",240,121,0)
	loadExtendedSprite(unpac_noheader(F9_Frame),"F9_Frame",240,85,0)
